function AnimatedAssistantMessageText({
  content,
  animate,
  onComplete,
}: {
  content: string;
  animate: boolean;
  onComplete?: () => void;
}) {
  const normalizedContent = String(content || "");

  // Tokenize into word+trailing-whitespace units so we reveal one word at a time.
  // The regex captures each word plus any whitespace that follows it, which means
  // re-joining the slice is lossless (no missing spaces or newlines).
  const tokens = useMemo(
    () => normalizedContent.match(/\S+\s*/g) ?? [],
    [normalizedContent],
  );

  const [visibleCount, setVisibleCount] = useState(() => (animate ? 0 : tokens.length));

  useEffect(() => {
    if (!animate || tokens.length === 0) {
      setVisibleCount(tokens.length);
      return;
    }

    setVisibleCount(0);
    let timeoutId: number | null = null;
    let completed = false;

    const revealNext = () => {
      setVisibleCount((current) => {
        if (current >= tokens.length) {
          if (!completed) {
            completed = true;
            onComplete?.();
          }
          return current;
        }

        const remaining = tokens.length - current;
        // One word at a time. Near the tail, keep it at 1 so the last words
        // land cleanly rather than in a sudden burst.
        const next = Math.min(tokens.length, current + 1);

        if (next >= tokens.length) {
          completed = true;
          window.setTimeout(() => onComplete?.(), 0);
        } else {
          // ~20 ms/word feels like a smooth, fast stream without chunking.
          // Slow very slightly on the first few words so the reader can latch on.
          const delay = current < 4 ? 30 : remaining <= 6 ? 16 : 20;
          timeoutId = window.setTimeout(revealNext, delay);
        }
        return next;
      });
    };

    timeoutId = window.setTimeout(revealNext, 60);

    return () => {
      if (timeoutId !== null) window.clearTimeout(timeoutId);
    };
  }, [animate, tokens, onComplete]);

  const isComplete = visibleCount >= tokens.length;
  const visibleText = tokens.slice(0, visibleCount).join("");

  return (
    <div className="whitespace-pre-wrap wrap-break-word text-[15px] leading-7 text-zinc-700">
      {visibleText}
      {animate && !isComplete ? (
        <span className="ml-0.5 inline-block h-5 w-1 rounded-full bg-blue-200 align-[-0.1em] animate-pulse" aria-hidden="true" />
      ) : null}
    </div>
  );
}

function PageHealthToast({
  pageHealthCheck,
  visible,
  onClose,
  onOpenBrief,
}: {
  pageHealthCheck: FunnelPageHealthCheck | null;
  visible: boolean;
  onClose: () => void;
  onOpenBrief?: () => void;
}) {
  if (!pageHealthCheck || !visible) return null;

  return (
    <div className="pointer-events-none absolute bottom-22 left-3 right-3 z-30 sm:bottom-24 sm:left-auto sm:right-4 sm:w-[320px]">
      <div
        className={classNames(
          "pointer-events-auto rounded-3xl border bg-white/96 p-4 shadow-[0_18px_50px_rgba(15,23,42,0.14)] backdrop-blur-sm transition-opacity duration-200",
          pageHealthCheck.tone === "watch" ? "border-amber-200" : "border-emerald-200",
        )}
      >
        <div className="flex items-start justify-between gap-3">
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2 text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-600">
              <span>{pageHealthCheck.label}</span>
              <span
                className={classNames(
                  "rounded-full border px-2 py-0.5 text-[9px]",
                  pageHealthCheck.tone === "watch"
                    ? "border-amber-300 bg-amber-50 text-amber-700"
                    : "border-emerald-300 bg-emerald-50 text-emerald-700",
                )}
              >
                {pageHealthCheck.tone === "watch" ? "Needs more context" : "Ready"}
              </span>
            </div>
            <div className="mt-2 text-sm leading-6 text-zinc-800">{pageHealthCheck.summary}</div>
            {pageHealthCheck.watchouts[1] ? (
              <div className="mt-1 text-[12px] leading-5 text-zinc-600">Also: {pageHealthCheck.watchouts[1]}</div>
            ) : null}
          </div>
          <button
            type="button"
            onClick={onClose}
            className="shrink-0 rounded-full border border-zinc-200 bg-white px-2 py-1 text-[11px] font-semibold text-zinc-500 transition-colors hover:bg-zinc-50 hover:text-zinc-900"
            aria-label="Hide page guidance"
            title="Hide page guidance"
          >
            Hide
          </button>
        </div>

        <div className="mt-2 text-[11px] leading-5 text-zinc-500">
          Use Brief for page-specific direction. Business setup comes from the main business profile, not this page chat.
        </div>

        <div className="mt-3 flex flex-wrap gap-2 text-[10px] text-zinc-500">
          <span>{pageHealthCheck.states.snapshotReady ? "Snapshot ready" : "Snapshot stale"}</span>
          <span>{pageHealthCheck.states.transactionReady ? "Route ready" : "Route needs wiring"}</span>
          <span>Context {pageHealthCheck.metrics.contextSignals}</span>
          <span>Refs {pageHealthCheck.metrics.referenceCount}</span>
        </div>

        <div className="mt-3 flex flex-wrap gap-2">
          {onOpenBrief ? (
            <button
              type="button"
              onClick={onOpenBrief}
              className="rounded-xl border border-zinc-200 bg-white px-3 py-1.5 text-[11px] font-semibold text-zinc-700 transition-colors hover:bg-zinc-50 hover:text-zinc-950"
            >
              Open brief
            </button>
          ) : null}
        </div>
      </div>
    </div>
  );
}

function buildRevealedAssistantKeyMap(messages: Array<{ role: string; at?: string | null }>) {
  const nextKeys: Record<string, true> = {};
  messages.forEach((message, index) => {
    if (message.role !== "assistant") return;
    nextKeys[`${message.role}-${message.at || index}-${index}`] = true;
  });
  return nextKeys;
}

function DirectionWorkbenchPanel({
  routeLabel,
  pageTypeLabel,
  pageGoalUsesDefault,
  pageAnatomy,
  messages = [],
  busy = false,
  activityLabel,
  activityDetail,
  conversationKey,
  embedded = false,
  onOpenBrief,
  onAsk,
  onPrepareDraft,
  onModeChange,
  onAttach,
  onPaste,
  attachCount = 0,
  assistantContext,
  pageHealthCheck,
  publishedAudit,
  selectedTargetLabel,
  selectedTargetContextLine,
  selectionTools,
}: DirectionWorkbenchPanelProps) {
  const toast = useToast();
  const [chatMode, setChatMode] = useState<"plan" | "work">("plan");
  const [directionNote, setDirectionNote] = useState("");
  const [assistantDetailsOpen, setAssistantDetailsOpen] = useState(false);
  const [assistantDetailsPopoverStyle, setAssistantDetailsPopoverStyle] = useState<{ left: number; width: number } | null>(null);
  const [audioLoadingKey, setAudioLoadingKey] = useState<string | null>(null);
  const [audioPlayingKey, setAudioPlayingKey] = useState<string | null>(null);
  const [pageHealthToastVisible, setPageHealthToastVisible] = useState(pageHealthCheck?.tone === "watch");
  const [revealedAssistantKeys, setRevealedAssistantKeys] = useState<Record<string, true>>(() => buildRevealedAssistantKeyMap(messages.slice(-8)));
  const directionScrollRef = useRef<HTMLDivElement | null>(null);
  const assistantDetailsRef = useRef<HTMLDivElement | null>(null);
  const assistantDetailsButtonRef = useRef<HTMLButtonElement | null>(null);
  const assistantHeaderMetaRef = useRef<HTMLDivElement | null>(null);
  const audioElementRef = useRef<HTMLAudioElement | null>(null);
  const audioUrlCacheRef = useRef(new Map<string, string>());
  const previousConversationKeyRef = useRef(conversationKey);
  const setAssistantMode = useCallback((nextMode: "plan" | "work") => {
    setChatMode(nextMode);
    onModeChange?.(nextMode);
  }, [onModeChange]);

  const recentMessages = messages.slice(-8);
  const liveStatusLabel = busy
    ? chatMode === "work"
      ? "Applying the next pass"
      : "Reviewing the page"
    : null;
  const inlineActivityLabel = activityLabel || liveStatusLabel || (chatMode === "work" ? "Applying changes" : "Reviewing the page");
  const inlineActivityDetail = activityDetail && activityDetail !== inlineActivityLabel
    ? activityDetail
    : chatMode === "work"
      ? "Applying the requested changes to the current page pass before replying here."
      : "Reading the current page state before replying here.";
  const chatFooterClassName = embedded
    ? "shrink-0 border-t border-zinc-200/80 bg-white px-4 pb-4 pt-3 sm:px-5"
    : "shrink-0 border-t border-zinc-200/80 bg-white px-4 py-3 sm:px-5";
  const lensMeta = [pageTypeLabel, pageGoalUsesDefault ? "using default goal" : null, pageAnatomy?.sections ? `${pageAnatomy.sections} sections` : null]
    .filter(Boolean)
    .join(" - ");
  const modeRailClassName = "inline-flex items-center gap-1.5 rounded-2xl border border-zinc-200 bg-zinc-50/80 p-1";
  const modeButtonClassName = "rounded-xl px-3 py-1.5 text-xs font-medium transition-colors duration-150";
  const activeModeButtonClassName = "bg-white text-zinc-950 shadow-[0_6px_16px_rgba(15,23,42,0.08)]";
  const inactiveModeButtonClassName = "text-zinc-500 hover:bg-white/80 hover:text-zinc-950";
  const briefButtonClassName = "rounded-xl px-2.5 py-1.5 text-xs font-medium text-zinc-500 transition-colors duration-150 hover:bg-zinc-100 hover:text-zinc-950";
  const panelHeading = embedded ? "Page assistant" : routeLabel;
  const panelSubheading = embedded ? routeLabel : lensMeta;
  const assistantContextEntries = [
    assistantContext?.funnel ? { label: "Funnel", value: assistantContext.funnel } : null,
    assistantContext?.page ? { label: "Page", value: assistantContext.page } : null,
    assistantContext?.state ? { label: "State", value: assistantContext.state } : null,
    assistantContext?.booking ? { label: "Booking", value: assistantContext.booking } : null,
    assistantContext?.tracking ? { label: "Tracking", value: assistantContext.tracking } : null,
    assistantContext?.seo ? { label: "SEO", value: assistantContext.seo } : null,
    assistantContext?.commerce ? { label: "Commerce", value: assistantContext.commerce } : null,
  ].filter((entry): entry is { label: string; value: string } => Boolean(entry));
  const assistantPriorityContext = assistantContext?.commerce === "Needs offer binding"
    ? "Commerce needs setup"
    : assistantContext?.booking === "Needs route"
      ? "Booking needs route"
      : assistantContext?.state || "";
  const assistantSummaryParts = [
    selectedTargetLabel
      ? selectedTargetLabel
      : assistantContext?.page
        ? assistantContext.page
        : "",
    assistantPriorityContext,
  ].filter(Boolean);
  const assistantDetailsLabel = assistantContextEntries
    .map((entry) => `${entry.label}: ${entry.value}`)
    .join("\n");
  const assistantContextSummary = assistantSummaryParts.join(" · ");
  const pageHealthToggle = pageHealthCheck ? (
    <button
      type="button"
      onClick={() => setPageHealthToastVisible(true)}
      className={classNames(
        "shrink-0 rounded-full border px-2 py-0.5 text-[11px] font-medium transition-colors",
        pageHealthCheck.tone === "watch"
          ? "border-amber-200 bg-amber-50 text-amber-700 hover:bg-amber-100"
          : "border-emerald-200 bg-emerald-50 text-emerald-700 hover:bg-emerald-100",
      )}
      title={pageHealthCheck.summary}
    >
      Page guidance
    </button>
  ) : null;
  const publishedAuditCard = publishedAudit ? (
    publishedAudit.tone === "watch" ? (
      <div className="mt-2 rounded-2xl border border-amber-200 bg-amber-50/85 px-3 py-2.5">
        <div className="flex flex-wrap items-center gap-2 text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-600">
          <span>{publishedAudit.label}</span>
          <span className="rounded-full border border-amber-300 bg-white px-2 py-0.5 text-[9px] text-amber-700">Watch</span>
        </div>
        <div className="mt-1.5 text-xs leading-5 text-zinc-700">{publishedAudit.summary}</div>
        {publishedAudit.warnings[1] ? (
          <div className="mt-1 text-[11px] leading-5 text-zinc-600">Next focus: {publishedAudit.warnings[1]}</div>
        ) : null}
        <div className="mt-2 flex flex-wrap gap-2 text-[10px] text-zinc-500">
          <span>Fetch {publishedAudit.metrics.fetchMs}ms</span>
          <span>HTML {Math.max(1, Math.round(publishedAudit.metrics.htmlChars / 1000))}k</span>
          <span>Inline media {publishedAudit.metrics.inlineMediaCount}</span>
          <span>Live fetch {publishedAudit.liveUrl ? "verified" : "unresolved"}</span>
        </div>
      </div>
    ) : (
      <div className="mt-2 flex flex-wrap items-center gap-x-2 gap-y-1 rounded-xl border border-zinc-200/80 bg-zinc-50/70 px-3 py-2 text-[11px] text-zinc-600">
        <span className="rounded-full border border-zinc-200 bg-white px-2 py-0.5 text-[9px] font-semibold uppercase tracking-[0.14em] text-zinc-500">Live checked</span>
        <span className="text-zinc-700">{publishedAudit.summary}</span>
        <span>Fetch {publishedAudit.metrics.fetchMs}ms</span>
        <span>HTML {Math.max(1, Math.round(publishedAudit.metrics.htmlChars / 1000))}k</span>
      </div>
    )
  ) : null;

  useEffect(() => {
    setAssistantDetailsOpen(false);
  }, [assistantDetailsLabel, assistantContextSummary]);

  useEffect(() => {
    setChatMode("plan");
    setDirectionNote("");
  }, [conversationKey]);

  useEffect(() => {
    onModeChange?.(chatMode);
  }, [chatMode, onModeChange]);

  useEffect(() => {
    setPageHealthToastVisible(pageHealthCheck?.tone === "watch");
  }, [conversationKey, pageHealthCheck?.summary, pageHealthCheck?.tone]);

  useEffect(() => {
    if (previousConversationKeyRef.current === conversationKey) return;
    previousConversationKeyRef.current = conversationKey;
    setRevealedAssistantKeys(buildRevealedAssistantKeyMap(recentMessages));
  }, [conversationKey, recentMessages]);

  useEffect(() => {
    if (!assistantDetailsOpen) {
      setAssistantDetailsPopoverStyle(null);
      return;
    }

    const updateAssistantDetailsPopoverStyle = () => {
      const buttonRect = assistantDetailsButtonRef.current?.getBoundingClientRect();
      const headerRect = assistantHeaderMetaRef.current?.getBoundingClientRect();
      if (!buttonRect || !headerRect) return;

      const horizontalPadding = 8;
      const availableWidth = Math.max(headerRect.width - horizontalPadding * 2, 220);
      const width = Math.min(320, availableWidth);
      const preferredLeft = buttonRect.right - headerRect.left - width;
      const maxLeft = Math.max(headerRect.width - width - horizontalPadding, horizontalPadding);
      const left = Math.max(horizontalPadding, Math.min(preferredLeft, maxLeft));

      setAssistantDetailsPopoverStyle({ left, width });
    };

    updateAssistantDetailsPopoverStyle();
    window.addEventListener("resize", updateAssistantDetailsPopoverStyle);

    return () => {
      window.removeEventListener("resize", updateAssistantDetailsPopoverStyle);
    };
  }, [assistantDetailsOpen]);

  useEffect(() => {
    if (!assistantDetailsOpen) return;

    const handlePointerDown = (event: PointerEvent | MouseEvent) => {
      if (!assistantDetailsRef.current?.contains(event.target as Node)) {
        setAssistantDetailsOpen(false);
      }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setAssistantDetailsOpen(false);
      }
    };

    document.addEventListener("pointerdown", handlePointerDown, true);
    document.addEventListener("mousedown", handlePointerDown, true);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown, true);
      document.removeEventListener("mousedown", handlePointerDown, true);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, [assistantDetailsOpen]);

  const assistantContextMeta = assistantContextSummary ? (
    <div ref={assistantHeaderMetaRef} className="mt-1.5 min-w-0 text-[11px] text-zinc-500">
      <div className="flex min-w-0 flex-wrap items-start gap-2">
        <div className="min-w-0 flex-1 truncate pt-0.5">{assistantContextSummary}</div>
        {pageHealthToggle}
        {assistantContextEntries.length ? (
          <div ref={assistantDetailsRef} className="relative z-30 shrink-0">
            <button
              ref={assistantDetailsButtonRef}
              type="button"
              aria-expanded={assistantDetailsOpen}
              onClick={() => setAssistantDetailsOpen((open) => !open)}
              className="shrink-0 rounded-full border border-zinc-200 bg-zinc-50 px-2 py-0.5 font-medium text-zinc-600 hover:bg-zinc-100"
              title={assistantDetailsLabel}
            >
              Details
            </button>
            {assistantDetailsOpen && assistantDetailsPopoverStyle ? (
              <div
                className="absolute top-[calc(100%+0.5rem)] z-40 overflow-hidden rounded-2xl border border-zinc-200 bg-white shadow-[0_18px_42px_rgba(15,23,42,0.16)]"
                style={{ left: `${assistantDetailsPopoverStyle.left}px`, width: `${assistantDetailsPopoverStyle.width}px` }}
              >
                <div className="max-h-[min(20rem,calc(100vh-16rem))] overflow-y-auto p-3">
                  <div className="flex items-center justify-between gap-3 border-b border-zinc-100 pb-2">
                    <div className="text-[10px] font-semibold uppercase tracking-[0.14em] text-zinc-500">Assistant context</div>
                    <div className="text-[10px] text-zinc-400">Diagnostic</div>
                  </div>
                  <div className="mt-2 space-y-1.5 text-xs text-zinc-600">
                    {assistantContextEntries.map((entry) => (
                      <div key={`${entry.label}-${entry.value}`} className="rounded-xl bg-zinc-50/80 px-2.5 py-2">
                        <div className="text-[10px] font-semibold uppercase tracking-[0.12em] text-zinc-500">{entry.label}</div>
                        <div className="mt-1 wrap-break-word text-[12px] leading-5 text-zinc-800">{entry.value}</div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
    </div>
  ) : null;
  useEffect(() => {
    if (!directionScrollRef.current) return;
    directionScrollRef.current.scrollTo({ top: directionScrollRef.current.scrollHeight, behavior: "smooth" });
  }, [recentMessages.length]);

  const submitDirection = () => {
    const prompt = directionNote.trim();
    if (!prompt || busy) return;
    if (chatMode === "work") {
      onPrepareDraft(prompt, prompt);
    } else {
      onAsk(prompt);
    }
    setDirectionNote("");
  };

  const startPlanWork = (plan: SourceActionPlan) => {
    if (!plan?.moves?.length || busy) return;
    const prompt = [
      plan.summary,
      ...plan.moves.map((move, index) => `${index + 1}. ${move.target}: ${move.change}`),
      ...plan.watchouts.slice(0, 2).map((item) => `Watchout: ${item}`),
    ]
      .filter(Boolean)
      .join("\n");
    setAssistantMode("work");
    onPrepareDraft(prompt, prompt, { sourceActionPlan: plan });
  };

  const idleQuickActions = chatMode === "work"
    ? [
        {
          label: "Tighten the weakest part of this page",
          prompt: "Tighten the weakest part of this page and apply the strongest update without changing what is already clearly working.",
        },
        {
          label: "Apply the next highest-leverage pass",
          prompt: "Apply the next highest-leverage pass on this page and explain what changed in practical terms.",
        },
      ]
    : [
        {
          label: "What is making this page feel weak?",
          prompt: "What is making this page feel weak?",
        },
        {
          label: "What should change next before I keep polishing?",
          prompt: "What should change next before I keep polishing?",
        },
      ];
  const idleIntro = chatMode === "work"
    ? {
        eyebrow: "Apply mode",
        title: "Use this when you want a concrete pass, not another vague suggestion.",
        detail: "Point at the weak area, name the kind of change you want, and let the assistant push a real update into the page.",
      }
    : {
        eyebrow: "Ask mode",
        title: "Use this to diagnose what is off before you start changing things.",
        detail: "Ask for the weakest section, the missing trust signal, the muddy headline, or the next issue worth fixing.",
      };

  const stopReadAloud = useCallback(() => {
    const player = audioElementRef.current;
    if (player) {
      player.pause();
      player.currentTime = 0;
      player.onended = null;
      player.onerror = null;
    }
    setAudioPlayingKey(null);
    setAudioLoadingKey(null);
  }, []);

  const playReadAloudAudio = useCallback((messageKey: string, audioUrl: string) => {
    let player = audioElementRef.current;
    if (!player) {
      player = new Audio();
      audioElementRef.current = player;
    }

    player.pause();
    player.currentTime = 0;
    player.src = audioUrl;
    player.onended = () => setAudioPlayingKey((current) => (current === messageKey ? null : current));
    player.onerror = () => {
      setAudioPlayingKey((current) => (current === messageKey ? null : current));
      toast.error("Read aloud did not play. Retry here.");
    };

    const playback = player.play();
    if (playback && typeof playback.catch === "function") {
      playback.catch(() => {
        setAudioPlayingKey((current) => (current === messageKey ? null : current));
        toast.error("Read aloud did not start. Retry here.");
      });
    }
    setAudioPlayingKey(messageKey);
  }, [toast]);

  const handleReadAloud = useCallback(async (messageKey: string, content: string) => {
    const normalizedContent = String(content || "").trim();
    if (!normalizedContent) return;

    if (audioPlayingKey === messageKey) {
      stopReadAloud();
      return;
    }

    const cachedUrl = audioUrlCacheRef.current.get(messageKey);
    if (cachedUrl) {
      playReadAloudAudio(messageKey, cachedUrl);
      return;
    }

    stopReadAloud();
    setAudioLoadingKey(messageKey);
    try {
      const res = await fetch("/api/portal/funnel-builder/read-aloud", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ text: normalizedContent }),
      });
      if (!res.ok) {
        const json = (await res.json().catch(() => null)) as { error?: string } | null;
        throw new Error(normalizeFunnelEditorError("read aloud", json?.error || null, res.status));
      }

      const blob = await res.blob();
      const audioUrl = URL.createObjectURL(blob);
      audioUrlCacheRef.current.set(messageKey, audioUrl);
      playReadAloudAudio(messageKey, audioUrl);
    } catch (error) {
      const message = normalizeFunnelEditorError("read aloud", error);
      toast.error(message);
      setAudioPlayingKey(null);
    } finally {
      setAudioLoadingKey((current) => (current === messageKey ? null : current));
    }
  }, [audioPlayingKey, playReadAloudAudio, stopReadAloud, toast]);

  useEffect(() => () => {
    stopReadAloud();
    for (const audioUrl of audioUrlCacheRef.current.values()) {
      URL.revokeObjectURL(audioUrl);
    }
    audioUrlCacheRef.current.clear();
  }, [stopReadAloud]);

  return (
    <div className={classNames("relative flex min-h-0 flex-1 flex-col overflow-hidden", embedded ? "bg-transparent" : "rounded-3xl border border-zinc-200 bg-white") }>
      {!embedded ? (
        <div className="shrink-0 border-b border-zinc-200/80 bg-white px-4 py-2 sm:px-5">
          <div className="flex flex-wrap items-center justify-between gap-3">
            <div className="min-w-0 flex-1">
              <div className="truncate text-sm font-semibold text-zinc-950">{panelHeading}</div>
              {panelSubheading ? <div className="mt-1 truncate text-xs text-zinc-500">{panelSubheading}</div> : null}
              {assistantContextMeta}
              {publishedAuditCard}
            </div>
            <div className="ml-auto flex flex-wrap items-center justify-end gap-2">
              <div className={modeRailClassName}>
                <button
                  type="button"
                  onClick={() => setAssistantMode("plan")}
                  className={classNames(
                    modeButtonClassName,
                    chatMode === "plan" ? activeModeButtonClassName : inactiveModeButtonClassName,
                  )}
                >
                  Ask
                </button>
                <button
                  type="button"
                  onClick={() => setAssistantMode("work")}
                  className={classNames(
                    modeButtonClassName,
                    chatMode === "work" ? activeModeButtonClassName : inactiveModeButtonClassName,
                  )}
                >
                  Apply
                </button>
              </div>
              {onOpenBrief ? (
                <button
                  type="button"
                  onClick={onOpenBrief}
                  className={briefButtonClassName}
                >
                  Brief
                </button>
              ) : null}
            </div>
          </div>
        </div>
      ) : null}

      <div className={classNames("shrink-0 px-4 pt-2 pb-1.5 sm:px-5 sm:pb-2", embedded ? "bg-white" : "bg-transparent") }>
        <div className="mx-auto flex w-full max-w-4xl flex-wrap items-center justify-between gap-3">
          {embedded ? (
            <>
              <div className="min-w-0 flex flex-1 items-center gap-3">
                <div className="min-w-0 flex-1">
                  {routeLabel ? <div className="truncate text-sm font-semibold text-zinc-950">{routeLabel}</div> : null}
                  {lensMeta ? <div className="mt-0.5 truncate text-xs text-zinc-500">{lensMeta}</div> : null}
                  {assistantContextMeta}
                  {publishedAuditCard}
                </div>
                <div className={modeRailClassName}>
                  <button
                    type="button"
                    onClick={() => setAssistantMode("plan")}
                    className={classNames(
                      modeButtonClassName,
                      chatMode === "plan" ? activeModeButtonClassName : inactiveModeButtonClassName,
                    )}
                  >
                    Ask
                  </button>
                  <button
                    type="button"
                    onClick={() => setAssistantMode("work")}
                    className={classNames(
                      modeButtonClassName,
                      chatMode === "work" ? activeModeButtonClassName : inactiveModeButtonClassName,
                    )}
                  >
                    Apply
                  </button>
                </div>
                {onOpenBrief ? (
                  <button
                    type="button"
                    onClick={onOpenBrief}
                    className={briefButtonClassName}
                  >
                    Brief
                  </button>
                ) : null}
              </div>
            </>
          ) : null}
        </div>
      </div>

      <div ref={directionScrollRef} className={classNames("min-h-0 flex-1 overflow-y-auto px-4 sm:px-5", embedded ? "pb-18 pt-2.5 sm:pb-22" : "pb-20 pt-3 sm:pb-24") }>
        <div className="mx-auto w-full max-w-4xl space-y-5">
          {recentMessages.length ? (
            recentMessages.map((message, index) => (
              (() => {
                const messageKey = `${message.role}-${message.at || index}-${index}`;
                const readAloudBusy = audioLoadingKey === messageKey;
                const readAloudActive = audioPlayingKey === messageKey;
                const shouldAnimateAssistantMessage = message.role === "assistant" && !revealedAssistantKeys[messageKey];
                return (
              <div
                key={`direction-message-${messageKey}`}
                className={classNames("flex", message.role === "user" ? "justify-end" : "justify-start")}
              >
                {message.role === "user" ? (
                  <div className="ml-10 max-w-[min(42rem,100%)] rounded-3xl border border-sky-100 bg-[linear-gradient(180deg,#f8fbff_0%,#eef5ff_100%)] px-4 py-3.5 text-sm leading-relaxed text-slate-800 shadow-[0_10px_24px_rgba(59,130,246,0.08)]">
                    <div className="whitespace-pre-wrap">{message.content}</div>
                  </div>
                ) : (
                  <div className="mr-6 max-w-[min(52rem,100%)] space-y-3">
                    <div className="flex items-center justify-end">
                      <button
                        type="button"
                        onClick={() => void handleReadAloud(messageKey, message.content)}
                        disabled={readAloudBusy}
                        className={classNames(
                          "inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-medium transition-colors",
                          readAloudActive
                            ? "border-blue-200 bg-blue-50 text-blue-700 hover:bg-blue-100"
                            : "border-zinc-200 bg-white text-zinc-500 hover:border-zinc-300 hover:text-zinc-900",
                          readAloudBusy ? "cursor-wait opacity-70" : "",
                        )}
                        title={readAloudActive ? "Stop read aloud" : "Read aloud"}
                        aria-label={readAloudActive ? "Stop read aloud" : "Read aloud"}
                      >
                        <ReadAloudSpeakerIcon className="h-3.5 w-3.5" />
                        <span>{readAloudBusy ? "Reading..." : readAloudActive ? "Stop" : "Read aloud"}</span>
                      </button>
                    </div>
                    <AnimatedAssistantMessageText
                      content={message.content}
                      animate={shouldAnimateAssistantMessage}
                      onComplete={() => {
                        setRevealedAssistantKeys((current) => (current[messageKey] ? current : { ...current, [messageKey]: true }));
                      }}
                    />
                    {message.sourceActionPlan ? (
                      <div className="space-y-2.5 border-l-2 border-zinc-200 pl-3.5">
                        <div className="text-[10px] font-semibold uppercase tracking-[0.16em] text-zinc-500">Suggested pass</div>
                        <div className="space-y-2 text-sm leading-6 text-zinc-700">
                          {message.sourceActionPlan.moves.slice(0, 5).map((move) => (
                            <div key={`${message.at || index}-${move.key}`} className="min-w-0 wrap-break-word">
                              <span className="font-semibold text-zinc-950">{move.target}:</span>{" "}
                              <span>{move.change}</span>
                            </div>
                          ))}
                        </div>
                        {message.sourceActionPlan.watchouts.length ? (
                          <div className="text-xs leading-5 text-zinc-500">
                            <span className="font-semibold text-zinc-700">Watchouts:</span>{" "}
                            <span>{message.sourceActionPlan.watchouts.slice(0, 2).join(" · ")}</span>
                          </div>
                        ) : null}
                        <div>
                          <button
                            type="button"
                            onClick={() => startPlanWork(message.sourceActionPlan!)}
                            disabled={busy}
                            className="text-xs font-medium text-zinc-700 underline decoration-zinc-300 underline-offset-4 transition hover:text-zinc-950 hover:decoration-zinc-500 disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            Apply this pass
                          </button>
                        </div>
                      </div>
                    ) : null}
                  </div>
                )}
              </div>
                );
              })()
            ))
          ) : !busy ? (
            <div className="flex flex-col items-start gap-3 pt-2">
              <div className="max-w-120 rounded-3xl border border-zinc-200/80 bg-[linear-gradient(180deg,#ffffff_0%,#f8fafc_100%)] px-4 py-3.5 shadow-[0_12px_30px_rgba(15,23,42,0.04)]">
                <div className="text-[10px] font-semibold uppercase tracking-[0.16em] text-zinc-500">{idleIntro.eyebrow}</div>
                <div className="mt-2 text-sm font-semibold leading-6 text-zinc-950">{idleIntro.title}</div>
                <div className="mt-1.5 text-[13px] leading-6 text-zinc-600">{idleIntro.detail}</div>
              </div>
              {idleQuickActions.map((chip) => (
                <button
                  key={chip.label}
                  type="button"
                  onClick={() => {
                    if (chatMode === "work") {
                      onPrepareDraft(chip.prompt, chip.label);
                      return;
                    }
                    onAsk(chip.prompt);
                  }}
                  className="rounded-2xl border border-zinc-200 bg-white px-4 py-2.5 text-left text-sm text-zinc-700 transition-colors hover:border-zinc-300 hover:bg-zinc-50 hover:text-zinc-950"
                >
                  {chip.label}
                </button>
              ))}
            </div>
          ) : null}

          {busy ? (
            <div className="flex justify-start">
              <AssistantThinkingCard mode={chatMode} label={inlineActivityLabel} detail={inlineActivityDetail} />
            </div>
          ) : null}
        </div>
      </div>

      <PageHealthToast
        pageHealthCheck={pageHealthCheck || null}
        visible={pageHealthToastVisible}
        onClose={() => setPageHealthToastVisible(false)}
        onOpenBrief={onOpenBrief}
      />

      <div className={chatFooterClassName}>
        {selectedTargetLabel || selectedTargetContextLine ? (
          <div className="mx-auto mb-2 flex w-full max-w-4xl flex-wrap items-center gap-2 text-[11px] text-zinc-500">
            <span className="rounded-full border border-zinc-200 bg-zinc-50 px-2 py-0.5 font-semibold uppercase tracking-[0.14em] text-zinc-600">
              Editing
            </span>
            {selectedTargetLabel ? <span className="font-semibold text-zinc-800">{selectedTargetLabel}</span> : null}
            {selectedTargetContextLine ? <span className="truncate text-zinc-500">{selectedTargetContextLine}</span> : null}
          </div>
        ) : null}
        {selectionTools ? <div className="mx-auto mb-3 w-full max-w-4xl">{selectionTools}</div> : null}
        <PageAssistantComposerRow>
          <AiPromptComposer
            value={directionNote}
            onChange={setDirectionNote}
            onSubmit={submitDirection}
            onAttach={onAttach || (() => {})}
            onPaste={onPaste}
            placeholder={
              chatMode === "work"
                ? "Describe the pass to apply."
                : "Ask what feels weakest here."
            }
            busy={busy}
            busyLabel={inlineActivityLabel || "Thinking..."}
            attachCount={attachCount}
            tone="light"
          />
        </PageAssistantComposerRow>
      </div>
    </div>
  );
}

function CodeSurface({
  value,
  onChange,
  placeholder,
  readOnly = false,
  lineHighlightRange,
  seamless = false,
  tone = "dark",
  statusLabel,
  showStatusBar = true,
  editorSelectAllSignal = 0,
  onActivate,
}: {
  value: string;
  onChange?: (next: string) => void;
  placeholder?: string;
  readOnly?: boolean;
  lineHighlightRange?: { startLine: number; endLine: number } | null;
  seamless?: boolean;
  tone?: "dark" | "light";
  statusLabel?: string;
  showStatusBar?: boolean;
  editorSelectAllSignal?: number;
  onActivate?: () => void;
}) {
  const code = String(value || "");
  const lines = splitCodeLines(code || "");
  const renderedLines = splitCodeLines(code || placeholder || "");
  const readOnlyViewportRef = useRef<HTMLDivElement | null>(null);
  const readOnlyLineNumbersRef = useRef<HTMLDivElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const editLineNumbersRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    if (!lineHighlightRange?.startLine) return;
    if (readOnly) {
      const targetLine = readOnlyViewportRef.current?.querySelector(`[data-code-line="${lineHighlightRange.startLine}"]`) as HTMLElement | null;
      targetLine?.scrollIntoView({ block: "center", behavior: "smooth" });
      return;
    }

    const editor = textareaRef.current;
    if (!editor) return;
    const targetTop = Math.max((lineHighlightRange.startLine - 2) * CODE_SURFACE_LINE_HEIGHT + CODE_SURFACE_VERTICAL_PADDING, 0);
    editor.scrollTo({ top: targetTop, behavior: "smooth" });
  }, [lineHighlightRange?.endLine, lineHighlightRange?.startLine, readOnly]);

  useEffect(() => {
    if (readOnly || !textareaRef.current || editorSelectAllSignal <= 0) return;
    textareaRef.current.focus();
    textareaRef.current.select();
  }, [editorSelectAllSignal, readOnly]);

  const wasReadOnly = useRef(readOnly);
  useEffect(() => {
    if (!readOnly && wasReadOnly.current && textareaRef.current) {
      textareaRef.current.focus();
    }
    wasReadOnly.current = readOnly;
  }, [readOnly]);

  const syncEditGutterScroll = useCallback(() => {
    const editor = textareaRef.current;
    const gutter = editLineNumbersRef.current;
    if (!editor || !gutter) return;
    gutter.scrollTop = editor.scrollTop;
  }, []);

  const syncReadOnlyGutterScroll = useCallback(() => {
    const viewport = readOnlyViewportRef.current;
    const gutter = readOnlyLineNumbersRef.current;
    if (!viewport || !gutter) return;
    gutter.scrollTop = viewport.scrollTop;
  }, []);

  const isLight = tone === "light";
  const lineCount = Math.max(lines.length, 1);
  const shouldShowStatusBar = showStatusBar && !seamless;

  return (
    <div className={classNames(
      "flex min-h-0 flex-col overflow-hidden",
      "h-full flex-1",
      isLight ? "text-slate-700" : "text-zinc-100",
      seamless
        ? isLight
          ? "bg-transparent"
          : "bg-zinc-950"
        : isLight
          ? "rounded-[18px] border border-zinc-200/80 bg-white shadow-[inset_0_1px_0_rgba(255,255,255,0.9)]"
          : "rounded-[20px] border border-zinc-900 bg-zinc-950",
    )}>
      {shouldShowStatusBar ? (
        <div className={classNames(
          "shrink-0 border-b px-6 py-3 text-[11px] font-medium",
          isLight
            ? "border-zinc-200 bg-[linear-gradient(180deg,#ffffff_0%,#f4f4f5_100%)] text-zinc-700"
            : "border-zinc-900 bg-zinc-950/80 text-zinc-400",
        )}>
          {statusLabel || (readOnly ? "Viewing source" : "Editing staged source")} - {`${lineCount} ${lineCount === 1 ? "line" : "lines"}`}
        </div>
      ) : null}

      <div className={classNames("min-h-0 flex-1 overflow-hidden", seamless && isLight ? "bg-transparent" : isLight ? "bg-white" : "bg-zinc-950")}>
        {readOnly ? (
          <div
            className={classNames("relative flex h-full min-h-0", onActivate ? "group/csr" : "", isLight ? "bg-white" : "bg-zinc-950")}
            onClick={onActivate || undefined}
          >
            {onActivate ? (
              <>
                <div className="pointer-events-none absolute inset-0 z-10 opacity-0 ring-2 ring-inset ring-zinc-400/40 transition-opacity duration-100 group-hover/csr:opacity-100" />
                <div className="pointer-events-none absolute right-3 top-3 z-20 opacity-0 transition-opacity duration-100 group-hover/csr:opacity-100">
                  <span className="rounded-full bg-zinc-900 px-2.5 py-1 text-[10px] font-medium text-white shadow-sm">Click to edit</span>
                </div>
              </>
            ) : null}
            <div
              ref={readOnlyLineNumbersRef}
              aria-hidden="true"
              className={classNames(
                "shrink-0 overflow-hidden border-r px-2 py-3 pb-6 text-right text-[11px] leading-6 tabular-nums select-none",
                isLight ? "border-zinc-200 bg-zinc-50 text-zinc-400" : "border-zinc-900 bg-zinc-950 text-zinc-500",
              )}
            >
              {renderedLines.map((_, index) => (
                <div key={`readonly-line-${index}`} className="h-6 pr-1">
                  {index + 1}
                </div>
              ))}
            </div>
            <div
              ref={readOnlyViewportRef}
              onScroll={syncReadOnlyGutterScroll}
              className={classNames(
                "h-full max-h-[calc(100dvh-240px)] min-h-0 w-full overflow-x-auto overflow-y-auto overscroll-contain [scrollbar-gutter:stable] lg:max-h-none",
                onActivate ? "cursor-text" : "",
                seamless && isLight ? "bg-[linear-gradient(180deg,#fcfcfd_0%,#f8fafc_100%)]" : "",
              )}
            >
              <CodeSurfaceRenderedLines lines={renderedLines} lineHighlightRange={lineHighlightRange} tone={tone} />
            </div>
          </div>
        ) : (
          <div className={classNames("flex h-full min-h-0", isLight ? "bg-white" : "bg-zinc-950")}>
            <div
              ref={editLineNumbersRef}
              aria-hidden="true"
              className={classNames(
                "shrink-0 overflow-hidden border-r px-2 py-3 pb-6 text-right text-[11px] leading-6 tabular-nums select-none",
                isLight ? "border-zinc-200 bg-zinc-50 text-zinc-400" : "border-zinc-900 bg-zinc-950 text-zinc-500",
              )}
            >
              {renderedLines.map((_, index) => (
                <div key={`edit-line-${index}`} className="h-6 pr-1">
                  {index + 1}
                </div>
              ))}
            </div>
            <textarea
              ref={textareaRef}
              value={code}
              onChange={(e) => onChange?.(e.target.value)}
              onScroll={syncEditGutterScroll}
              wrap="off"
              spellCheck={false}
              className={classNames(
                "block h-full max-h-[calc(100dvh-240px)] min-h-0 w-full resize-none overflow-x-auto overflow-y-auto bg-transparent px-4 py-3 pb-6 text-[13.5px] leading-6 tracking-[0] antialiased outline-none [scrollbar-gutter:stable] lg:max-h-none",
                isLight
                  ? "text-zinc-800 caret-zinc-700 placeholder:text-zinc-400 selection:bg-zinc-300/35"
                  : "text-zinc-100 caret-cyan-300 placeholder:text-zinc-500 selection:bg-white/15",
              )}
              style={{ tabSize: 2, fontFamily: CODE_SURFACE_FONT_FAMILY }}
              placeholder={placeholder}
            />
          </div>
        )}
      </div>
    </div>
  );
}

function PageAssistantComposerRow({
  leading,
  children,
}: {
  leading?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div className="mx-auto w-full max-w-4xl">
      <div className="flex flex-col gap-2 lg:flex-row lg:items-center">
        {leading ? <div className="shrink-0">{leading}</div> : null}
        <div className="min-w-0 flex-1">{children}</div>
      </div>
    </div>
  );
}

const WHOLE_PAGE_LENS_WINDOW_CLASS_NAME = "flex min-h-0 flex-1 flex-col overflow-hidden rounded-3xl border border-zinc-200/80 bg-[linear-gradient(180deg,#fbfcfe_0%,#f5f7fb_100%)] shadow-[0_20px_50px_rgba(15,23,42,0.06)]";
const WHOLE_PAGE_LENS_WINDOW_SUBTLE_CLASS_NAME = "flex min-h-0 flex-1 flex-col overflow-hidden rounded-3xl border border-zinc-200/70 bg-[linear-gradient(180deg,#fcfdfd_0%,#f8fafc_100%)] shadow-[0_12px_30px_rgba(15,23,42,0.04)]";
const WHOLE_PAGE_LENS_HEADER_CLASS_NAME = "shrink-0 border-b border-zinc-200/80 bg-white px-4 py-3 sm:px-5";
const WHOLE_PAGE_LENS_HEADER_SUBTLE_CLASS_NAME = "shrink-0 border-b border-zinc-200/70 bg-zinc-50/60 px-4 py-2.5 sm:px-5";
const WHOLE_PAGE_LENS_FOOTER_CLASS_NAME = "shrink-0 border-t border-zinc-200/80 bg-white px-4 py-3 sm:px-5";

function shouldOpenQuickCalendarForAiQuestion(question: string) {
  const text = String(question || "").toLowerCase();
  return /\b(calendar|booking calendar|schedule|book a call|book a meeting|appointment)\b/.test(text)
    && /\b(name|create|link|enable)\b/.test(text);
}

function WholePageLensWindow({
  label,
  title,
  meta,
  actions,
  children,
  footer,
  bodyClassName,
  headerHidden = false,
  compactHeader = false,
  tone = "default",
}: {
  label: string;
  title: string;
  meta?: string | null;
  actions?: React.ReactNode;
  children: React.ReactNode;
  footer?: React.ReactNode;
  bodyClassName?: string;
  headerHidden?: boolean;
  compactHeader?: boolean;
  tone?: "default" | "subtle";
}) {
  return (
    <div className={tone === "subtle" ? WHOLE_PAGE_LENS_WINDOW_SUBTLE_CLASS_NAME : WHOLE_PAGE_LENS_WINDOW_CLASS_NAME}>
      {!headerHidden ? (
        <div
          className={classNames(
            tone === "subtle" ? WHOLE_PAGE_LENS_HEADER_SUBTLE_CLASS_NAME : WHOLE_PAGE_LENS_HEADER_CLASS_NAME,
            "overflow-hidden transition-[max-height,opacity,padding,border-color] duration-200 ease-out max-h-32 opacity-100",
          )}
        >
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div className="min-w-0">
              {compactHeader ? (
                <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
                  <div className="text-sm font-semibold text-zinc-900">{title}</div>
                  {meta ? <div className="text-xs text-zinc-500">{meta}</div> : null}
                </div>
              ) : (
                <>
                  <div className="text-[11px] font-semibold uppercase tracking-[0.16em] text-zinc-400">{label}</div>
                  <div className="mt-1 text-sm font-semibold text-zinc-900">{title}</div>
                  {meta ? <div className="mt-1 text-xs text-zinc-500">{meta}</div> : null}
                </>
              )}
            </div>
            {actions ? <div className="flex flex-wrap items-center gap-2">{actions}</div> : null}
          </div>
        </div>
      ) : null}

      <div className={classNames("min-h-0 flex-1", bodyClassName)}>{children}</div>

      {footer ? <div className={WHOLE_PAGE_LENS_FOOTER_CLASS_NAME}>{footer}</div> : null}
    </div>
  );
}

function describeSectionPlanItem(item: string, index: number, total: number) {
  const normalized = item.trim().toLowerCase();

  if (normalized.includes("hero")) {
    return "Top of page. Set the promise, orient the visitor, and make the next step visible immediately.";
  }
  if (/(proof|trust|testimonial|logo|social proof)/.test(normalized)) {
    return "Credibility beat. Show evidence early so the main claim feels believable fast.";
  }
  if (/(offer|deliverable|includes|breakdown)/.test(normalized)) {
    return "Explain what the visitor gets and why it is worth taking the next step.";
  }
  if (/(reassurance|expectation|expectations|faq|objection)/.test(normalized)) {
    return "Remove resistance. Clarify objections, process, or what happens after the click.";
  }
  if (/(who it is for|\bfit\b|audience)/.test(normalized)) {
    return "Qualify fit. Help the right visitor lean in and let the wrong one self-sort.";
  }
  if (/(cta|capture|book|apply|schedule|next step)/.test(normalized)) {
    return "Conversion moment. Make the action obvious, specific, and low friction.";
  }
  if (index === 0) {
    return "Opening beat. The first screen should clarify the promise and the action path quickly.";
  }
  if (index === total - 1) {
    return "Closing beat. End with reassurance and a clear push into the next step.";
  }
  return "Distinct section beat. Give this part a clear job instead of letting the page flatten into one continuous slab.";
}

function SectionPlanHintRow({ item, index, total }: { item: string; index: number; total: number }) {
  const hint = describeSectionPlanItem(item, index, total);

  return (
    <div className="group relative flex items-start gap-3 rounded-xl border border-zinc-200/80 bg-white/90 px-3 py-2">
      <div className="flex w-8 shrink-0 flex-col items-center pt-0.5">
        <div className="text-[11px] font-semibold tabular-nums text-zinc-500">
          {(index + 1).toString().padStart(2, "0")}
        </div>
        {index < total - 1 ? <div aria-hidden="true" className="mt-1 h-5 w-px rounded-full bg-zinc-200" /> : null}
      </div>
      <div className="min-w-0">
        <div className="text-sm font-semibold leading-6 text-zinc-900">{item}</div>
      </div>
      <div className="pointer-events-none absolute left-9 right-3 top-[calc(100%+6px)] z-20 rounded-2xl border border-zinc-200 bg-white/98 px-3 py-2 text-xs leading-5 text-zinc-600 opacity-0 shadow-[0_16px_30px_rgba(15,23,42,0.08)] transition-[opacity,transform] duration-150 ease-out translate-y-1 group-hover:translate-y-0 group-hover:opacity-100">
        {hint}
      </div>
    </div>
  );
}

function AiPromptComposer({
  value,
  onChange,
  onSubmit,
  onAttach,
  onPaste,
  placeholder,
  busy,
  busyLabel,
  attachCount,
  className,
  tone = "light",
}: {
  value: string;
  onChange: (next: string) => void;
  onSubmit: () => void;
  onAttach: () => void;
  onPaste?: (event: ClipboardEvent<HTMLTextAreaElement>) => void;
  placeholder: string;
  busy: boolean;
  busyLabel: string;
  attachCount: number;
  className?: string;
  tone?: "light" | "dark";
}) {
  const canSubmit = !busy && value.trim().length > 0;
  const darkTone = tone === "dark";
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const composerStatusLabel = attachCount ? `${attachCount} reference${attachCount === 1 ? "" : "s"} attached` : null;
  const statusTextColorClassName = busy ? (darkTone ? "text-zinc-500" : "text-zinc-500") : darkTone ? "text-zinc-500" : "text-zinc-500";
  const showStatusRow = busy || Boolean(composerStatusLabel);

  useEffect(() => {
    const node = textareaRef.current;
    if (!node) return;
    node.style.height = "0px";
    node.style.height = `${Math.min(node.scrollHeight, 220)}px`;
    node.style.overflowY = node.scrollHeight > 220 ? "auto" : "hidden";
    if (!value.trim()) node.scrollTop = 0;
  }, [value]);

  return (
    <div
      className={classNames(
        "relative flex flex-col gap-0.5 border-b px-1 py-0.5 transition-colors",
        darkTone
          ? "border-zinc-700 text-zinc-100 focus-within:border-zinc-500"
          : "border-zinc-300/75 text-zinc-900 focus-within:border-zinc-500",
        className,
      )}
      aria-busy={busy}
    >
      <div className="flex items-end gap-2">
        <AiSparkIcon className={classNames("mb-1.5 h-3.5 w-3.5 shrink-0", busy ? (darkTone ? "text-zinc-600" : "text-zinc-300") : darkTone ? "text-zinc-500" : "text-zinc-400")} />
        <textarea
          ref={textareaRef}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          onPaste={onPaste}
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey && canSubmit) {
              onSubmit();
            }
          }}
          className={classNames(
            "min-w-0 flex-1 resize-none overflow-y-hidden rounded-2xl px-0 py-1.5 text-[14px] leading-5 tracking-[-0.01em] outline-none transition-colors",
            darkTone ? "text-zinc-50 placeholder:text-zinc-500" : "text-zinc-900 placeholder:text-zinc-400",
            "bg-transparent",
          )}
          style={{ minHeight: 36, maxHeight: 220 }}
          rows={1}
          placeholder={placeholder}
        />
        <div className="mb-0.5 flex shrink-0 items-center gap-1">
          <button
            type="button"
            disabled={busy}
            onClick={onAttach}
            className={classNames(
              "relative inline-flex h-8 w-8 items-center justify-center rounded-full transition-colors disabled:opacity-60",
              darkTone ? "text-zinc-500 hover:text-zinc-100" : "text-zinc-400 hover:text-zinc-700",
              attachCount ? "text-brand-blue" : "",
            )}
            title={attachCount ? `${attachCount} reference${attachCount === 1 ? "" : "s"} attached` : "Attach references to AI"}
            aria-label={attachCount ? `${attachCount} reference${attachCount === 1 ? "" : "s"} attached` : "Attach references to AI"}
          >
            <svg aria-hidden="true" viewBox="0 0 24 24" className="h-4 w-4" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <path d="M21.44 11.05l-9.19 9.19a6 6 0 0 1-8.49-8.49l9.19-9.19a4 4 0 0 1 5.66 5.66l-9.2 9.19a2 2 0 0 1-2.83-2.83l8.49-8.48" />
            </svg>
            {attachCount ? (
              <span className="absolute -right-1 -top-1 inline-flex min-w-4 items-center justify-center rounded-full bg-brand-blue px-1 text-[10px] font-semibold leading-4 text-white">
                {attachCount > 9 ? "9+" : attachCount}
              </span>
            ) : null}
          </button>

          <button
            type="button"
            disabled={!canSubmit}
            onClick={onSubmit}
            className={classNames(
              "group inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full transition-all duration-100 hover:scale-105 disabled:opacity-50",
              darkTone ? "text-zinc-400 hover:text-zinc-100" : "text-zinc-500 hover:text-zinc-900",
              canSubmit ? "" : darkTone ? "pointer-events-none text-zinc-700" : "pointer-events-none text-zinc-300",
            )}
            title={busy ? busyLabel : "Send prompt to AI"}
            aria-label={busy ? busyLabel : "Send prompt to AI"}
          >
            {busy ? (
              <SpinnerIcon className="h-4 w-4" />
            ) : (
              <>
                <span className="group-hover:hidden">
                  <IconSend size={16} />
                </span>
                <span className="hidden group-hover:inline">
                  <IconSendHover size={16} />
                </span>
              </>
            )}
          </button>
        </div>
      </div>

      {showStatusRow ? (
        <div className={classNames("flex items-center gap-2 px-7 pb-0.5 text-[11px] tracking-[0.01em]", statusTextColorClassName)}>
          {busy ? (
            <>
              <AssistantTypingDots tone={darkTone ? "dark" : "light"} />
              <span className="min-w-0 truncate">{busyLabel}</span>
            </>
          ) : composerStatusLabel ? <span className="min-w-0 truncate">{composerStatusLabel}</span> : null}
        </div>
      ) : null}
    </div>
  );
}

function escapeEditorPreviewText(value: string) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;");
}

function extractClipboardImageFiles(data: DataTransfer | null | undefined) {
  const deduped = new Map<string, File>();

  for (const file of Array.from(data?.files || [])) {
    if (!(file instanceof File)) continue;
    if (!String(file.type || "").toLowerCase().startsWith("image/")) continue;
    const key = `${file.name}:${file.size}:${file.type}`;
    deduped.set(key, file);
  }

  for (const item of Array.from(data?.items || [])) {
    if (!item || item.kind !== "file") continue;
    if (!String(item.type || "").toLowerCase().startsWith("image/")) continue;
    const file = item.getAsFile();
    if (!(file instanceof File)) continue;
    const key = `${file.name}:${file.size}:${file.type}`;
    deduped.set(key, file);
  }

  return Array.from(deduped.values());
}

function readEditorPreviewAttr(attrs: string, name: string) {
  const match = attrs.match(new RegExp(`\\b${name}=(['\"])([\\s\\S]*?)\\1`, "i"));
  return match ? String(match[2] || "") : "";
}

function getEditorPreviewEmbedHeight(attrs: string) {
  const style = readEditorPreviewAttr(attrs, "style");
  const styleHeight = style.match(/(?:^|;)\s*height\s*:\s*(\d+)px/i);
  if (styleHeight) return Math.max(120, Math.min(2000, Number(styleHeight[1] || 0)));

  const rawHeight = readEditorPreviewAttr(attrs, "height");
  const parsedHeight = Number(rawHeight || 0);
  if (Number.isFinite(parsedHeight) && parsedHeight > 0) {
    return Math.max(120, Math.min(2000, parsedHeight));
  }

  return 420;
}

function buildEditorEmbedPlaceholder(title: string, src: string, heightPx: number) {
  const safeTitle = escapeEditorPreviewText(title || "Embedded content");
  const safeSrc = escapeEditorPreviewText(src || "");
  return `<div data-editor-embed-placeholder="1" style="width:100%;min-height:${heightPx}px;border:1px solid #e4e4e7;border-radius:18px;background:linear-gradient(180deg,#ffffff 0%,#f8fafc 100%);display:flex;align-items:center;justify-content:center;padding:24px;"><div style="width:min(100%,420px);text-align:center;color:#334155;font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;"><div style="font-size:11px;font-weight:700;letter-spacing:0.14em;text-transform:uppercase;color:#94a3b8;">Editor preview</div><div style="margin-top:10px;font-size:18px;font-weight:700;color:#0f172a;">${safeTitle}</div><div style="margin-top:8px;font-size:13px;line-height:1.5;color:#475569;">Live embeds are paused in the editor preview so blocks and whole-page stay on the same page surface.</div><div style="margin-top:14px;display:inline-flex;max-width:100%;align-items:center;gap:8px;border:1px solid #e2e8f0;border-radius:999px;background:#ffffff;padding:8px 12px;font-size:12px;color:#64748b;">${safeSrc}</div></div></div>`;
}

function buildEditorPreviewHtml(html: string) {
  if (!html.trim()) return "";

  return html.replace(/<iframe\b([\s\S]*?)\bsrc=(['\"])(.*?)\2([\s\S]*?)><\/iframe>/gi, (match, beforeSrc, _quote, rawSrc, afterSrc) => {
    const src = String(rawSrc || "").trim();
    if (!src) return match;

    const normalized = src.toLowerCase();
    const isEditorSensitiveEmbed =
      normalized.includes("/forms/") ||
      normalized.includes("/book/u/") ||
      normalized.includes("/embed/chatbot") ||
      normalized.includes("embed=1");

    if (!isEditorSensitiveEmbed) return match;

    const attrs = `${beforeSrc || ""} ${afterSrc || ""}`;
    const title = readEditorPreviewAttr(attrs, "title") || "Embedded content";
    const heightPx = getEditorPreviewEmbedHeight(attrs);
    return buildEditorEmbedPlaceholder(title, src, heightPx);
  });
}

function neutralizePreviewHeaderLogoLink(html: string) {
  if (!html.trim()) return "";

  return html.replace(
    /(<div[^>]*class="pa-header"[^>]*><div class="pa-header-inner">)\s*<a\b([^>]*?)href=(['"])(?:\/|#)\3([^>]*)>([\s\S]*?)<\/a>/i,
    (_match, prefix: string, beforeHref: string, _quote: string, afterHref: string, inner: string) =>
      `${prefix}<span${beforeHref}${afterHref}>${inner}</span>`,
  );
}

function hasEmbeddedBookingRuntimeInHtml(html: string) {
  return /(<iframe\b[^>]*\bsrc=['"][^'"]*\/book\/|\/book\/[^"]+\/c\/|\/book\/u\/[^"'\s/]+\/[^"'?&#/]+|calendarembed|booking widget|calendar widget|data-editor-implicit-booking-preview|data-pa-booking-runtime|\{\{\s*(?:PURE_)?BOOKING_APP\s*\}\})/i.test(html);
}

function hasBookingSectionHeadingInHtml(html: string) {
  return /<h([1-6])[^>]*>\s*(?:Book a time|Book time|Schedule a call|Schedule your call|Schedule a consultation|Schedule a discovery call)\s*<\/h\1>/i.test(html);
}

function injectImplicitBookingPreviewHtml(opts: {
  html: string;
  bookingSiteSlug?: string | null;
  calendarId?: string | null;
  calendarTitle?: string | null;
  funnelId?: string | null;
  pageId?: string | null;
  surfaceContext?: BookingSurfaceContext | null;
}) {
  const html = String(opts.html || "");
  const bookingSiteSlug = String(opts.bookingSiteSlug || "").trim();
  const calendarId = String(opts.calendarId || "").trim();
  if (!html.trim() || !bookingSiteSlug || !calendarId) return html;
  if (html.includes("data-editor-implicit-booking-preview=\"1\"")) return html;
  if (hasEmbeddedBookingRuntimeInHtml(html)) return html;

  const safeCalendarTitle = escapeEditorPreviewText(String(opts.calendarTitle || calendarId).trim() || calendarId);
  const runtimeHtml = buildBookingRuntimePlaceholderHtml({
    slug: bookingSiteSlug,
    calendarId,
    surfaceContext: opts.surfaceContext || null,
  });
  const embedHtml = [
    `<div data-editor-implicit-booking-preview="1" style="margin-top:24px;display:flex;flex-direction:column;gap:12px;">`,
    `<div style="display:inline-flex;align-self:flex-start;max-width:100%;border:1px solid #bbf7d0;border-radius:999px;background:#f0fdf4;padding:6px 10px;font:600 11px/1.2 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;letter-spacing:0.08em;text-transform:uppercase;color:#15803d;">Linked funnel calendar · ${safeCalendarTitle}</div>`,
    runtimeHtml,
    `</div>`,
  ].join("");

  const bookingHeadingPattern = /(<h([1-6])[^>]*>\s*(?:Book a time|Book time|Schedule a call|Schedule your call|Schedule a consultation|Schedule a discovery call)\s*<\/h\2>)/i;
  if (bookingHeadingPattern.test(html)) {
    return html.replace(bookingHeadingPattern, `$1${embedHtml}`);
  }

  const sectionHtml = [
    `<section data-editor-implicit-booking-preview="1" style="margin:48px auto 0;max-width:960px;padding:0 24px 24px;">`,
    `<h2 style="margin:0 0 16px;font:700 42px/1.1 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#0f172a;">Book a time</h2>`,
    embedHtml,
    `</section>`,
  ].join("");

  if (/<\/main>/i.test(html)) return html.replace(/<\/main>/i, `${sectionHtml}</main>`);
  if (/<\/body>/i.test(html)) return html.replace(/<\/body>/i, `${sectionHtml}</body>`);
  return `${html}${sectionHtml}`;
}

function humanizeBuilderSectionLabel(value: string) {
  return String(value || "")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function collectBuilderSectionPlanItems(rawBlocks: unknown) {
  const blocks = Array.isArray(rawBlocks) ? rawBlocks : [];
  const labels: string[] = [];

  for (let index = 0; index < blocks.length; index += 1) {
    const block = blocks[index] as Record<string, any> | null;
    if (!block || typeof block !== "object" || block.type !== "section") continue;
    const props = block.props && typeof block.props === "object" ? block.props : {};
    const children = Array.isArray((props as any).children) ? ((props as any).children as Array<Record<string, any>>) : [];
    const heading = children.find((child) => child && child.type === "heading" && typeof child.props?.text === "string");
    const headingText = typeof heading?.props?.text === "string" ? heading.props.text.trim() : "";
    const anchorLabel = typeof (props as any).anchorId === "string" ? humanizeBuilderSectionLabel((props as any).anchorId) : "";
    const label = headingText || anchorLabel || `Section ${index + 1}`;
    if (!label || labels.includes(label)) continue;
    labels.push(label);
  }

  return labels.slice(0, 8);
}

async function convertPreviewImageDataUrlToPngDataUrl(
  dataUrl: string,
  options?: { maxWidth?: number; maxHeight?: number },
): Promise<string> {
  const maxWidth = Math.max(120, Math.min(2400, Number(options?.maxWidth || 1600) || 1600));
  const maxHeight = Math.max(120, Math.min(3200, Number(options?.maxHeight || 1800) || 1800));

  const img = new window.Image();
  img.src = dataUrl;
  await new Promise<void>((resolve, reject) => {
    img.onload = () => resolve();
    img.onerror = () => reject(new Error("Invalid preview image"));
  });

  const srcW = Math.max(1, img.naturalWidth || img.width || 1);
  const srcH = Math.max(1, img.naturalHeight || img.height || 1);
  const ratio = Math.min(1, maxWidth / srcW, maxHeight / srcH);
  const dstW = Math.max(1, Math.floor(srcW * ratio));
  const dstH = Math.max(1, Math.floor(srcH * ratio));

  const canvas = document.createElement("canvas");
  canvas.width = dstW;
  canvas.height = dstH;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas not supported");
  ctx.clearRect(0, 0, dstW, dstH);
  ctx.drawImage(img, 0, 0, dstW, dstH);
  return canvas.toDataURL("image/png");
}

function waitForFrameLoad(frame: HTMLIFrameElement) {
  return new Promise<void>((resolve, reject) => {
    const timeout = window.setTimeout(() => {
      cleanup();
      reject(new Error("Preview frame timed out"));
    }, 8000);

    const cleanup = () => {
      window.clearTimeout(timeout);
      frame.removeEventListener("load", onLoad);
      frame.removeEventListener("error", onError);
    };

    const onLoad = () => {
      cleanup();
      resolve();
    };
    const onError = () => {
      cleanup();
      reject(new Error("Preview frame failed to load"));
    };

    frame.addEventListener("load", onLoad);
    frame.addEventListener("error", onError);
  });
}

function waitForAnimationFrames(count: number) {
  return new Promise<void>((resolve) => {
    const step = (remaining: number) => {
      if (remaining <= 0) {
        resolve();
        return;
      }
      window.requestAnimationFrame(() => step(remaining - 1));
    };
    step(Math.max(1, count));
  });
}

async function captureRenderedPreviewDataUrl(input: {
  html: string;
  previewDevice: "desktop" | "mobile";
}) {
  if (typeof document === "undefined") return "";
  const html = String(input.html || "").trim();
  if (!html) return "";

  const host = document.createElement("div");
  const frame = document.createElement("iframe");
  const width = input.previewDevice === "mobile" ? 430 : 1280;
  const height = input.previewDevice === "mobile" ? 1200 : 1500;

  host.style.position = "fixed";
  host.style.left = "-20000px";
  host.style.top = "0";
  host.style.width = `${width}px`;
  host.style.height = `${height}px`;
  host.style.opacity = "0";
  host.style.pointerEvents = "none";
  host.style.overflow = "hidden";

  frame.setAttribute("sandbox", "allow-forms allow-popups allow-scripts allow-same-origin");
  frame.setAttribute("aria-hidden", "true");
  frame.style.width = `${width}px`;
  frame.style.height = `${height}px`;
  frame.style.border = "0";
  frame.srcdoc = html;
  host.appendChild(frame);
  document.body.appendChild(host);

  try {
    await waitForFrameLoad(frame);
    const doc = frame.contentDocument;
    const win = frame.contentWindow;
    if (!doc || !win) return "";
    if (doc.fonts?.ready) {
      await Promise.race([
        doc.fonts.ready,
        new Promise<void>((resolve) => window.setTimeout(resolve, 1200)),
      ]).catch(() => null);
    }
    await waitForAnimationFrames(2);
    const root = (doc.documentElement || doc.body) as HTMLElement | null;
    if (!root) return "";
    const rawDataUrl = await toPng(root, {
      cacheBust: true,
      pixelRatio: 1,
      backgroundColor: "#ffffff",
      canvasWidth: width,
      canvasHeight: Math.max(height, root.scrollHeight || height),
      skipAutoScale: true,
    });
    return await convertPreviewImageDataUrlToPngDataUrl(rawDataUrl, {
      maxWidth: input.previewDevice === "mobile" ? 900 : 1600,
      maxHeight: input.previewDevice === "mobile" ? 1600 : 1800,
    });
  } finally {
    host.remove();
  }
}

function buildStandaloneCustomCodePreviewHtml(html: string, css: string) {
  const bodyHtml = String(html || "").trim();
  const styleCss = String(css || "").trim();
  if (!bodyHtml && !styleCss) return "";

  return [
    "<!doctype html>",
    '<html lang="en">',
    "<head>",
    '  <meta charset="utf-8" />',
    '  <meta name="viewport" content="width=device-width, initial-scale=1" />',
    '  <title>Custom code preview</title>',
    "  <style>",
    "    html, body { margin: 0; padding: 0; background: #ffffff; color: #0f172a; }",
    "    body { font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; }",
    "    .editor-preview-shell { min-height: 100vh; padding: 0; }",
    styleCss,
    "  </style>",
    "</head>",
    '<body><div class="editor-preview-shell">',
    bodyHtml,
    "</div></body>",
    "</html>",
  ].join("\n");
}

type HtmlRegionScope = {
  key: string;
  label: string;
  summary: string;
  html: string;
  sourceIndex: number;
};

function normalizeInlineText(value: string) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

function buildHtmlRegionScope(el: Element, sourceIndex: number): HtmlRegionScope {
  const text = normalizeInlineText(el.textContent || "").toLowerCase();
  const meta = normalizeInlineText([
    el.getAttribute("id") || "",
    el.getAttribute("class") || "",
    el.getAttribute("data-section") || "",
    el.getAttribute("aria-label") || "",
  ].join(" ")).toLowerCase();
  const heading = normalizeInlineText(el.querySelector("h1, h2, h3, h4, h5, h6")?.textContent || "");

  let label = "";
  if (/\bfooter\b/.test(`${text} ${meta}`)) {
    label = "Footer";
  } else if (sourceIndex === 0 && (el.querySelector("h1") || /\bhero\b/.test(meta))) {
    label = "Hero";
  } else if (el.querySelector("form") || /\b(form|apply|signup|sign up|contact)\b/.test(text)) {
    label = /\b(book|schedule|calendar)\b/.test(text) ? "Booking" : "Form";
  } else if (/\b(testimonial|testimonials|review|reviews|results|success stor)\b/.test(`${text} ${meta}`)) {
    label = "Testimonials";
  } else if (/\b(faq|question|questions|common questions)\b/.test(`${text} ${meta}`)) {
    label = "FAQ";
  } else if (/\b(pricing|plans|packages)\b/.test(`${text} ${meta}`)) {
    label = "Pricing";
  } else if (/\b(shop|product|products|checkout|cart|buy now|offer)\b/.test(`${text} ${meta}`)) {
    label = "Offer";
  } else if (/\b(cta|get started|start now|apply now|book now)\b/.test(`${text} ${meta}`)) {
    label = "CTA";
  } else if (heading) {
    label = heading.slice(0, 48);
  } else {
    label = `Section ${sourceIndex + 1}`;
  }

  const summary = heading || normalizeInlineText(el.textContent || "").slice(0, 180) || `${label} region`;
  return {
    key: `${label.toLowerCase().replace(/[^a-z0-9]+/g, "-") || "section"}-${sourceIndex}`,
    label,
    summary,
    html: el.outerHTML.slice(0, 24000),
    sourceIndex,
  };
}

function getHtmlRegionElements(doc: Document): Element[] {
  const preferredSelectors = ":scope > main > section, :scope > section, :scope > main > div, :scope > div";
  const preferred = Array.from(doc.body?.querySelectorAll(preferredSelectors) || []).filter(
    (el) => normalizeInlineText(el.textContent || "").length > 0,
  );
  if (preferred.length > 0) return preferred;

  return Array.from(doc.body?.children || []).filter((el) => normalizeInlineText(el.textContent || "").length > 0);
}

function detectHtmlRegionScopes(html: string): HtmlRegionScope[] {
  if (!html.trim() || typeof DOMParser === "undefined") return [];

  try {
    const doc = new DOMParser().parseFromString(html, "text/html");
    return getHtmlRegionElements(doc)
      .slice(0, 8)
      .map((el, index) => buildHtmlRegionScope(el, index));
  } catch {
    return [];
  }
}

function formatMoney(cents: number | null | undefined, currency: string) {
  if (typeof cents !== "number" || !Number.isFinite(cents)) return "";
  const curr = (currency || "usd").toUpperCase();
  try {
    return new Intl.NumberFormat(undefined, { style: "currency", currency: curr }).format(cents / 100);
  } catch {
    return `${curr} ${(cents / 100).toFixed(2)}`;
  }
}

function describeBuilderAiTarget(block: CreditFunnelBlock | null) {
  if (!block) return "the page canvas";

  switch (block.type) {
    case "customCode":
      return "the selected code block";
    case "section":
      return "the selected section";
    case "columns":
      return "the selected columns block";
    case "heading":
      return "the selected heading";
    case "paragraph":
      return "the selected text block";
    case "formEmbed":
    case "formLink":
      return "the selected form block";
    case "calendarEmbed":
      return "the selected booking block";
    case "image":
    case "video":
      return "the selected media block";
    default:
      return "the selected block";
  }
}

function describeBuilderBlockNoun(block: CreditFunnelBlock | null) {
  const described = describeBuilderAiTarget(block);
  if (described.startsWith("the selected ")) return described.slice("the selected ".length);
  if (described.startsWith("the ")) return described.slice("the ".length);
  return described;
}

