        summary: `Selected heading text with current copy: ${currentText}.`,
        contextLine: `Current heading: ${currentText}`,
        blockType: selectedBlock.type,
        blockId: selectedBlock.id,
        currentState: {
          scope: "text",
          fieldKind: "heading",
          text: currentText,
        },
